window.addEventListener('load', function() {
    
document.getElementById('Env_load').style.display = 'none';
document.getElementById('Env_main').style.display = 'flex';

});

function 切换页面(name) {
    
    const hiddenForm = document.createElement('form');
    hiddenForm.method = 'POST';
    hiddenForm.action = name;
    hiddenForm.style.display = 'none';
    
    const usernameInput = document.createElement('input');
    usernameInput.type = 'hidden';
    usernameInput.name = 'developer_uid';
    usernameInput.value = 开发者UID;
    hiddenForm.appendChild(usernameInput);
    
    const passwordInput = document.createElement('input');
    passwordInput.type = 'hidden';
    passwordInput.name = 'developer_password';
    passwordInput.value = 开发者密码;
    hiddenForm.appendChild(passwordInput);
    
    const tokenInput = document.createElement('input');
    tokenInput.type = 'hidden';
    tokenInput.name = 'developer_token';
    tokenInput.value = 开发者Token;
    hiddenForm.appendChild(tokenInput);
    
    document.body.appendChild(hiddenForm);
    hiddenForm.submit();
    document.body.removeChild(hiddenForm);
}



function 等待动画(内容) {

    const 已有加载弹窗 = document.querySelector('.等待动画弹窗');
    if (已有加载弹窗) 已有加载弹窗.remove();
    
    const 加载弹窗 = document.createElement('div');
    加载弹窗.className = '等待动画弹窗';
    加载弹窗.classList.add('弹窗遮罩');
    加载弹窗.innerHTML = `
        <div class="弹窗背景">
            <div class="弹窗内部" style="width:280px; text-align: center; padding: 30px 20px;">
                <div style="font-size: 40px; color: #27ae60; margin-bottom: 15px;">
                    <i class="fas fa-spinner fa-spin"></i>
                </div>
                <div style="font-size: 14px; color: #666;">${内容}</div>
            </div>
        </div>
    `;
    document.body.appendChild(加载弹窗);
}



function 删除等待动画() {

const modal = document.querySelector('.等待动画弹窗');
if (modal) {
    modal.remove();
}
}




function 获取API链接(API接口,name) {
    const baseUrl = API接口.replace(/\/$/, '');
    const endpoint = name.replace(/^\//, '');
    return `${baseUrl}/${endpoint}`;
}




function alert(message, 状态) {
    const type = 状态 ? 'success' : 'error';
    const duration = 3000;
    const icon = 状态
        ? `<svg viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg" stroke="currentColor" class="arco-icon arco-icon-check-circle-fill" stroke-width="4" stroke-linecap="butt" stroke-linejoin="miter"><path fill-rule="evenodd" clip-rule="evenodd" d="M24 44c11.046 0 20-8.954 20-20S35.046 4 24 4 4 12.954 4 24s8.954 20 20 20Zm10.207-24.379a1 1 0 0 0 0-1.414l-1.414-1.414a1 1 0 0 0-1.414 0L22 26.172l-4.878-4.88a1 1 0 0 0-1.415 0l-1.414 1.415a1 1 0 0 0 0 1.414l7 7a1 1 0 0 0 1.414 0l11.5-11.5Z" fill="currentColor" stroke="none"></path></svg>`
        : `<svg viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg" stroke="currentColor" class="arco-icon arco-icon-close-circle-fill" stroke-width="4"><path fill-rule="evenodd" clip-rule="evenodd" d="M24 44c11.046 0 20-8.954 20-20S35.046 4 24 4 4 12.954 4 24s8.954 20 20 20Zm-5.657-27.314a1 1 0 0 1 1.414 0L24 20.93l4.243-4.243a1 1 0 1 1 1.414 1.414L25.414 22.343l4.243 4.243a1 1 0 0 1-1.414 1.414L24 23.757l-4.243 4.243a1 1 0 0 1-1.414-1.414l4.243-4.243-4.243-4.243a1 1 0 0 1 0-1.414Z" fill="currentColor" stroke="none"></path></svg>`;

    if (!document.querySelector('#arcoMessageStyles')) {
        const style = document.createElement('style');
        style.id = 'arcoMessageStyles';
        style.textContent = `
            .arco-overlay-message {
                position: fixed;
                top: 0;
                left: 0;
                width: 100%;
                pointer-events: none;
                z-index: 5001;
            }
            .arco-message-list {
                display: flex;
                flex-direction: column;
                align-items: center;
                list-style: none;
                margin: 0;
                padding: 0;
            }
            .arco-message-list-top {
                padding-top: 40px;
            }
            .arco-message {
                display: inline-flex;
                align-items: center;
                box-sizing: border-box;
                padding: 10px 16px;
                margin-bottom: 12px;
                border-radius: 4px;
                font-size: 14px;
                line-height: 1.5715;
                color: var(--color-text-1, #1d2129);
                background: var(--color-bg-popup, #fff);
                box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);
                pointer-events: auto;
                animation: arcoMessageFadeInOut 2s ease forwards;
            }
            .arco-message-icon {
                display: inline-flex;
                align-items: center;
                margin-right: 8px;
                font-size: 16px;
            }
            .arco-message-icon svg {
                width: 1em;
                height: 1em;
            }
            .arco-message-content {
                display: inline-block;
            }
            .arco-message-success .arco-message-icon {
                color: #00b42a;
            }
            .arco-message-error .arco-message-icon {
                color: #f53f3f;
            }
            @keyframes arcoMessageFadeInOut {
                0% {
                    opacity: 0;
                    transform: translateY(-100%);
                }
                10% {
                    opacity: 1;
                    transform: translateY(0);
                }
                90% {
                    opacity: 1;
                    transform: translateY(0);
                }
                100% {
                    opacity: 0;
                    transform: translateY(-100%);
                }
            }
        `;
        document.head.appendChild(style);
    }

    let overlay = document.querySelector('.arco-overlay-message');
    if (!overlay) {
        overlay = document.createElement('div');
        overlay.className = 'arco-overlay arco-overlay-message';

        const list = document.createElement('ul');
        list.className = 'arco-message-list arco-message-list-top';

        overlay.appendChild(list);
        document.body.appendChild(overlay);
    }

    const list = overlay.querySelector('.arco-message-list');

    const li = document.createElement('li');
    li.setAttribute('role', 'alert');
    li.className = `arco-message arco-message-${type}`;
    li.style.animationDuration = duration + 'ms';

    const iconSpan = document.createElement('span');
    iconSpan.className = 'arco-message-icon';
    iconSpan.innerHTML = icon;

    const contentSpan = document.createElement('span');
    contentSpan.className = 'arco-message-content';
    contentSpan.textContent = message;

    li.appendChild(iconSpan);
    li.appendChild(contentSpan);
    list.appendChild(li);

    setTimeout(() => {
        if (li.parentNode) {
            li.parentNode.removeChild(li);
        }
        if (list && list.children.length === 0 && overlay.parentNode) {
            overlay.parentNode.removeChild(overlay);
        }
    }, duration);
}
